"""SQLAlchemy building blocks shared by every entity's `models.py`."""

import uuid
from datetime import datetime
from enum import StrEnum
from typing import ClassVar

from pydantic import TypeAdapter
from sqlalchemy import DateTime, Dialect, Enum, MetaData, func
from sqlalchemy.dialects.postgresql import JSONB
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column
from sqlalchemy.types import TypeDecorator

# Stable constraint names, so autogenerated migrations can drop/alter them later.
NAMING_CONVENTION = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING_CONVENTION)


# Mixin columns use `sort_order` so the id is the first column and timestamps the last.
class IdMixin:
    """UUIDv7 primary key generated by the backend (ADR-0023)."""

    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, default=uuid.uuid7, sort_order=-1)


class CreatedAtMixin:
    """Insert time, set by the database."""

    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now(), sort_order=1)


class UpdatedAtMixin:
    """Last update time, set by the database."""

    # eager_defaults: the new `updated_at` is fetched with RETURNING; a lazy refresh would fail under asyncio.
    __mapper_args__: ClassVar[dict[str, object]] = {"eager_defaults": True}

    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), onupdate=func.now(), sort_order=1
    )


def str_enum(enum: type[StrEnum], name: str) -> Enum:
    """`varchar` column with a CHECK constraint on the enum's values; SQLAlchemy would store member names (ADR-0031).

    `alembic check` ignores CHECK constraints, so a new enum value needs a hand-written migration.
    """
    return Enum(
        enum,
        name=name,
        native_enum=False,
        create_constraint=True,
        length=32,
        values_callable=lambda e: [member.value for member in e],
        validate_strings=True,
    )


class PydanticJSONB[T](TypeDecorator[T]):
    """`jsonb` column holding a DTO value object, validated on load (ADR-0030).

    Assign a new value to change it; in-place mutation is not tracked. `None` is stored as SQL `NULL`.
    """

    impl = JSONB
    cache_ok = True

    def __init__(self, adapter: TypeAdapter[T]) -> None:
        super().__init__(none_as_null=True)
        self.adapter = adapter

    def process_bind_param(self, value: T | None, dialect: Dialect) -> object:
        if value is None:
            return None
        return self.adapter.dump_python(value, mode="json", by_alias=True)

    def process_result_value(self, value: object, dialect: Dialect) -> T | None:
        if value is None:
            return None
        return self.adapter.validate_python(value)
